import React, { useState } from 'react';
import WalletConnect from './components/WalletConnect';
import './App.css';

function App() {
  // State lưu thông tin ví
  const [walletInfo, setWalletInfo] = useState(null);

  // Callback khi kết nối/ngắt kết nối ví
  const handleWalletConnected = (info) => {
    setWalletInfo(info);
  };

  return (
    <div className="app">
      {/* Header */}
      <header className="app-header">
        <h1>🏛️ Auction DApp - Đấu giá trên Blockchain</h1>
        <p className="subtitle">Ứng dụng đấu giá phi tập trung sử dụng MetaMask</p>
      </header>

      {/* Main content */}
      <main className="app-main">
        {/* Component kết nối ví */}
        <WalletConnect onWalletConnected={handleWalletConnected} />

        {/* Hiển thị thông tin khi đã kết nối */}
        {walletInfo && (
          <div className="welcome-section">
            <h2>🎉 Chào mừng bạn đến với Auction DApp!</h2>
            <p>
              Bạn đã kết nối thành công với ví{' '}
              <strong>{walletInfo.account.slice(0,6)}...{walletInfo.account.slice(-4)}</strong>
            </p>
            <p>Số dư: <strong>{parseFloat(walletInfo.balance).toFixed(4)} ETH</strong></p>
            <p className="note">
              ⚡ Tiếp theo: Chúng ta sẽ tích hợp smart contract đấu giá
            </p>
            
            {/* Preview các tính năng sắp có */}
            <div className="features-preview">
              <h3>📋 Các tính năng sắp có:</h3>
              <ul>
                <li>✅ Xem sản phẩm đấu giá</li>
                <li>✅ Xem giá cao nhất hiện tại</li>
                <li>✅ Đặt giá mới</li>
                <li>✅ Xem thời gian còn lại</li>
                <li>✅ Kết thúc đấu giá (Admin)</li>
              </ul>
            </div>
          </div>
        )}
      </main>

      {/* Footer */}
      <footer className="app-footer">
        <p>© 2024 Auction DApp - Dự án học tập Blockchain</p>
        <p>🛠️ Công nghệ: React + ethers.js + MetaMask</p>
      </footer>
    </div>
  );
}

export default App;
